pub fn msg_name(id: u16) -> Option<&'static str> {
    MSG_NAMES
        .binary_search_by_key(&id, |&(k, _)| k)
        .ok()
        .map(|i| MSG_NAMES[i].1)
}

pub fn response_id_for(req_id: u16) -> Option<u16> {
    REQUESTS
        .binary_search_by_key(&req_id, |&(k, _)| k)
        .ok()
        .map(|i| REQUESTS[i].1)
}

